import java.util.ArrayList;
import java.util.List;

final class KruskalMSTTest {
    private KruskalMSTTest() {
    }

    public static void main(String[] args) {
        shouldComputeSampleMst();
        shouldHandleSingleVertexGraph();
        shouldDetectDisconnectedGraphs();
        shouldProtectGraphEdgesFromMutation();
        shouldProtectResultEdgesFromMutation();
        shouldRejectMalformedEdges();
        shouldRejectOutOfRangeVertices();
        System.out.println("All KruskalMST checks passed.");
    }

    private static void shouldComputeSampleMst() {
        Edge[] edges = {
            new Edge(0, 1, 10),
            new Edge(1, 3, 15),
            new Edge(2, 3, 4),
            new Edge(2, 0, 6),
            new Edge(0, 3, 5)
        };

        MstResult result = KruskalMST.minimumSpanningTree(WeightedGraph.of(4, edges));
        assertEquals(19, result.totalWeight(), "sample graph");
        assertTrue(result.isSpanningTree(), "sample graph should be connected");
        assertEquals(3, result.edges().size(), "sample graph edge count");
        assertEquals(19, KruskalMST.kruskalsMST(4, edges), "legacy sample graph");
        assertEquals(19, KruskalMST.kruskalsMST(4, new int[][] {
            {0, 1, 10}, {1, 3, 15}, {2, 3, 4}, {2, 0, 6}, {0, 3, 5}
        }), "sample graph via raw arrays");
    }

    private static void shouldHandleSingleVertexGraph() {
        MstResult result = KruskalMST.minimumSpanningTree(WeightedGraph.of(1, new Edge[0]));
        assertEquals(0, result.totalWeight(), "single-vertex graph");
        assertTrue(result.isSpanningTree(), "single-vertex graph should be connected");
    }

    private static void shouldRejectMalformedEdges() {
        expectIllegalArgument("malformed raw edge", () -> KruskalMST.kruskalsMST(4, new int[][] {{0, 1}}));
        expectIllegalArgument("null edge", () -> KruskalMST.kruskalsMST(4, new Edge[] {null}));
    }

    private static void shouldRejectOutOfRangeVertices() {
        expectIllegalArgument("out-of-range vertex", () -> KruskalMST.kruskalsMST(3, new Edge[] {new Edge(0, 3, 1)}));
    }

    private static void shouldDetectDisconnectedGraphs() {
        MstResult result = KruskalMST.minimumSpanningTree(WeightedGraph.of(4, new Edge[] {
            new Edge(0, 1, 2),
            new Edge(2, 3, 3)
        }));

        assertEquals(5, result.totalWeight(), "disconnected graph");
        assertFalse(result.isSpanningTree(), "disconnected graph should not be marked as a spanning tree");
        assertEquals(2, result.edges().size(), "disconnected graph edge count");
    }

    private static void shouldProtectGraphEdgesFromMutation() {
        List<Edge> sourceEdges = new ArrayList<>(List.of(
            new Edge(0, 1, 10),
            new Edge(1, 3, 15),
            new Edge(2, 3, 4),
            new Edge(2, 0, 6),
            new Edge(0, 3, 5)
        ));

        WeightedGraph graph = WeightedGraph.of(4, sourceEdges);
        sourceEdges.set(0, new Edge(9, 9, 9));

        assertEquals(19, KruskalMST.minimumSpanningTree(graph).totalWeight(), "graph edges should be defensive copies");
        assertEquals(10, graph.edges().get(0).weight(), "graph should not reflect source list mutation");
        expectUnsupportedOperation("graph edges should be immutable", () -> graph.edges().add(new Edge(9, 9, 9)));
    }

    private static void shouldProtectResultEdgesFromMutation() {
        MstResult result = KruskalMST.minimumSpanningTree(WeightedGraph.of(4, new Edge[] {
            new Edge(0, 1, 10),
            new Edge(1, 3, 15),
            new Edge(2, 3, 4),
            new Edge(2, 0, 6),
            new Edge(0, 3, 5)
        }));

        expectUnsupportedOperation("result edges should be immutable", () -> result.edges().add(new Edge(9, 9, 9)));
        assertEquals(3, result.edges().size(), "result edges should remain intact");
        assertEquals(4, result.edges().get(0).weight(), "result edges should not be mutable through accessors");
        assertEquals(19, result.totalWeight(), "result total weight should stay stable");
    }

    private static void assertEquals(int expected, int actual, String scenario) {
        if (expected != actual) {
            throw new AssertionError(
                scenario + ": expected " + expected + " but got " + actual
            );
        }
    }

    private static void expectIllegalArgument(String scenario, Runnable action) {
        try {
            action.run();
        } catch (IllegalArgumentException expected) {
            return;
        }

        throw new AssertionError(scenario + ": expected IllegalArgumentException");
    }

    private static void expectUnsupportedOperation(String scenario, Runnable action) {
        try {
            action.run();
        } catch (UnsupportedOperationException expected) {
            return;
        }

        throw new AssertionError(scenario + ": expected UnsupportedOperationException");
    }

    private static void assertTrue(boolean value, String scenario) {
        if (!value) {
            throw new AssertionError(scenario + ": expected true");
        }
    }

    private static void assertFalse(boolean value, String scenario) {
        if (value) {
            throw new AssertionError(scenario + ": expected false");
        }
    }
}

